import{M as t}from"./chunks/MicroarchDiagram.DrgIqI9i.js";import{o as i,c as e,a2 as a,E as l}from"./chunks/framework.CNQbXYGB.js";const p=JSON.parse('{"title":"1.3 · 数据路径、缓存与同步","description":"","frontmatter":{"outline":2},"headers":[],"relativePath":"03-memory/memory-hierarchy.md","filePath":"03-memory/memory-hierarchy.md"}'),d={name:"03-memory/memory-hierarchy.md"},k=Object.assign(d,{setup(h){return(n,s)=>(i(),e("div",null,[s[0]||(s[0]=a('<h1 id="_1-3-·-数据路径、缓存与同步" tabindex="-1">1.3 · 数据路径、缓存与同步 <a class="header-anchor" href="#_1-3-·-数据路径、缓存与同步" aria-label="Permalink to &quot;1.3 · 数据路径、缓存与同步&quot;">​</a></h1><p>在 1.1 的向量加法中，CPU 把数组 A、B 复制到 DCU，然后启动 Kernel。拿线程 7 举例，它从设备数组读取 <code>A[7]</code> 和 <code>B[7]</code>，把两个值放进寄存器，算完再写到 <code>C[7]</code>。这一节沿着这三个数走一遍，再看相邻线程需要互相传数据时要做什么。</p><h2 id="_1-数据分别放在哪里" tabindex="-1">1. 数据分别放在哪里 <a class="header-anchor" href="#_1-数据分别放在哪里" aria-label="Permalink to &quot;1. 数据分别放在哪里&quot;">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>用向量加法理解</th><th>谁决定放什么</th></tr></thead><tbody><tr><td>主机内存</td><td>CPU 初始化的 <code>a</code>、<code>b</code> 和最终用来校验的 <code>c</code></td><td>Host 程序分配，<code>hipMemcpy</code> 在主机和设备之间复制</td></tr><tr><td>设备全局内存（本例由 HBM 显存提供）</td><td><code>hipMalloc</code> 分配的设备端 A、B、C 数组，可被各 Block 访问</td><td>程序分配数组，通过全局地址访问</td></tr><tr><td>L1 / L2 缓存</td><td>读 <code>A[7]</code> 时，硬件可能从已经缓存的数据中取值。L1 靠近 CU，L2 可服务多个 CU</td><td>硬件根据访问路径和缓存策略管理</td></tr><tr><td>寄存器</td><td>线程 7 加载到的两个输入和加法结果可暂存在自己对应的 VGPR lane 位置，数组基地址等统一值可用 SGPR</td><td>编译器按数据和指令分配</td></tr><tr><td>LDS（片上共享存储）</td><td>向量加法各算各的。若线程 7 要把自己的值交给同一 Block 的线程 8，可以用 <code>__shared__</code> 数组暂存</td><td>Kernel 决定谁写、谁读，以及何时同步</td></tr></tbody></table><p>这里的“全局内存”描述程序用什么地址访问数组。一次全局加载能否由缓存直接响应，要看当时的访问情况。LDS 则有程序明确指定的读写位置，同一个 CU 上的不同 Block 各用自己的 LDS 分配区。</p>',5)),l(t,{kind:"memory"}),s[1]||(s[1]=a(`<h2 id="跟一条加载指令" tabindex="-1">2. 从全局地址到加法 <a class="header-anchor" href="#跟一条加载指令" aria-label="Permalink to &quot;2. 从全局地址到加法 {#跟一条加载指令}&quot;">​</a></h2><p>先看一行 HIP 代码 <code>c[i] = a[i] + b[i]</code>。按 <a href="./../01-overview/software-stack.html#动手运行">1.1 的命令</a>编译后，在 BW100 的设备汇编里可以沿着寄存器找这五步。以下片段省略了地址计算等指令。</p><div class="language-asm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">asm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">global_load_dword  v4, v[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], off</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">; 此处省略了为第二个输入数组计算地址的指令，v[2:3] 已更新</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">global_load_dword  v2, v[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], off</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s_waitcnt vmcnt(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">v_add_f32_e32      v2, v4, v2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">global_store_dword v[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], v2, off</span></span></code></pre></div><ol><li>两条 <code>global_load_dword</code> 分别读取 A、B，把结果带回 <code>v4</code>、<code>v2</code>。每个有效 lane 都有自己的数据。</li><li><code>s_waitcnt vmcnt(0)</code> 等这个 wave 的相关向量访存完成。发出加载指令到数据可用之间有一段时间。</li><li><code>v_add_f32_e32</code> 读取这两个值，把加法结果放回 <code>v2</code>，<code>global_store_dword</code> 再把它写到 C。</li></ol><p>回到线程 7。主机把 A 初始化为下标，把 B 初始化为下标的两倍，因此这两个输入是 7 和 14。等它们到齐后，加法得到 21，写回 C[7]。沿着汇编可以确定数据进入哪个寄存器；要知道加载可能在哪一级缓存命中，还要看设备和访问方式。</p><p>像这样按 lane 访问数组的加载称为向量访存（VMEM）。如果编译器能证明一个地址和结果由整个 wave 共用，也可使用标量访存（SMEM），例如 E06 的 <code>s_load_dword</code>。想练习跟踪指令，可以在 1.1 生成的设备端 <code>.s</code> 中圈出两次加载的目标寄存器，再看加法是否读取了它们。</p><h2 id="_3-bw100-的-l1-和-l2-有多大" tabindex="-1">3. BW100 的 L1 和 L2 有多大 <a class="header-anchor" href="#_3-bw100-的-l1-和-l2-有多大" aria-label="Permalink to &quot;3. BW100 的 L1 和 L2 有多大&quot;">​</a></h2><p>在 <strong>BW100（gfx936）、DTK 26.04</strong> 上，<code>rocminfo</code> 的 BW100 设备条目打印 <code>L1: 32 KB</code> 和 <code>L2: 8192 KB</code>。按二进制单位写就是 <strong>32 KiB</strong> 和 <strong>8 MiB</strong>。其中 L2 也与 <a href="./../baselines/bw100-gfx936.html">HIP 设备属性记录</a>一致。</p><p><code>rocminfo</code> 的摘要每层只显示一个数。再看 Linux KFD 驱动（向运行时提供设备拓扑）的缓存明细，可以看到一级缓存分了几类。</p><table tabindex="0"><thead><tr><th>BW100 驱动报告</th><th style="text-align:right;">每条记录的容量</th><th style="text-align:right;">条目数</th></tr></thead><tbody><tr><td>L1 数据缓存</td><td style="text-align:right;">32 KiB</td><td style="text-align:right;">64</td></tr><tr><td>L1 数据缓存</td><td style="text-align:right;">16 KiB</td><td style="text-align:right;">64</td></tr><tr><td>L1 指令缓存</td><td style="text-align:right;">32 KiB</td><td style="text-align:right;">64</td></tr><tr><td>L2 数据缓存</td><td style="text-align:right;">8 MiB</td><td style="text-align:right;">1</td></tr></tbody></table><p>指令缓存服务取指，数据缓存服务数据读取。L1 表中的容量对应单条拓扑记录。两类数据缓存分别服务哪些加载，可结合下方实验理解。驱动在这里将两类都标为数据缓存，E06 的结果与向量路径可利用 32 KiB、标量路径可利用 16 KiB 的解释相符。工作集的转折也会随地址间距变化，缓存的共享范围和替换行为需要更细的对照。<a href="https://kernel.googlesource.com/pub/scm/linux/kernel/git/torvalds/linux/+/69050f8d6d075dc01af7a5f2f550a8067510366f/drivers/gpu/drm/amd/amdkfd/kfd_topology.c#1618" target="_blank" rel="noreferrer">KFD 拓扑实现</a> · <a href="./../labs/lab08-memory-latency-ladder.html">E06 完整结果</a></p><p>BW100 的 HIP 设备属性另有一个 <strong>每 Block 最多 64 KiB LDS</strong> 的报告值。LDS 是第 1 节里给线程交换数据的共享空间，这个上限和上表的缓存容量是两项不同的设备属性。<a href="https://github.com/mantuoluozk/dcu-microarch-guide/blob/main/experiments/01_device_info_and_isa.hip" target="_blank" rel="noreferrer">HIP 设备属性探测源码</a></p><details class="details custom-block"><summary>查看自己机器的缓存报告</summary><p>先运行 <code>rocminfo</code>，找到 <code>Marketing Name</code> 为 BW100 且 <code>Name</code> 为 gfx936 的设备条目，查看 <code>Cache Info</code>。要看驱动明细，把下面的 8 换成同一条目里显示的 <code>Node</code> 编号。这个步骤适用于能访问该拓扑的 Linux DTK 环境。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rocminfo</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">8</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;^(level|size|type) &#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/class/kfd/kfd/topology/nodes/&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/caches/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/properties</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  paste</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sort</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uniq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span></span></code></pre></div><p>每行开头是同类记录的数量，<code>level</code> 是缓存级别，<code>size</code> 在此报告以 KiB 计。<code>type 9</code> 对应设备数据缓存，<code>type 10</code> 对应设备指令缓存。</p></details><h2 id="区分三种等待" tabindex="-1">4. 谁在等什么 <a class="header-anchor" href="#区分三种等待" aria-label="Permalink to &quot;4. 谁在等什么 {#区分三种等待}&quot;">​</a></h2><p>假设一个 128 线程的 Block 要交换数据。在 BW100 上，线程 0 和线程 64 属于不同 wave。让每个线程先写入自己的 <code>tile[threadIdx.x]</code>，全 Block 一起执行 <code>__syncthreads()</code>，之后线程 64 才能读线程 0 写的 <code>tile[0]</code>。同一个 Block 的线程需要到达同一个屏障，尾部线程也要参与同步，可用条件控制屏障前后的读写。</p><table tabindex="0"><thead><tr><th>谁在等</th><th>等什么</th><th>在本节的例子</th></tr></thead><tbody><tr><td>一个 wave</td><td>自己已经发出的相关操作完成</td><td><code>s_waitcnt vmcnt(0)</code> 之后，向量加法才使用加载结果</td></tr><tr><td>同一个 Block 的线程</td><td>其他线程到达共同的同步点，以便安全读取这轮写入的数据</td><td>写 LDS 后执行 <code>__syncthreads()</code>，再读另一 wave 写的数据</td></tr><tr><td>CPU 上的 Host</td><td>已提交的设备工作完成</td><td>1.1 中，<code>hipDeviceSynchronize()</code> 返回后，Host 复制 C 回来校验</td></tr></tbody></table><p>同一 wave 内交换值还可以用 Shuffle，例如 <code>__shfl_down</code>。需要把 Block 内所有 wave 的结果汇总时，可以先各 wave 自己规约，再通过 LDS 和 Block 屏障合并。<a href="./../labs/lab05-wave-shuffle-reduction.html">E05 Wave Shuffle 实验</a></p><h2 id="_5-动手实战-·-看数据变多后加载何时变慢" tabindex="-1">5. 动手实战 · 看数据变多后加载何时变慢 <a class="header-anchor" href="#_5-动手实战-·-看数据变多后加载何时变慢" aria-label="Permalink to &quot;5. 动手实战 · 看数据变多后加载何时变慢&quot;">​</a></h2><p>这个小实验让一个线程沿一组打乱顺序的地址反复读取，每次读到的值是下一次要访问的位置。后一跳必须等待前一跳。我们只改这组数据占用的地址范围，观察完成一跳平均要等多久。这里的<strong>工作集</strong>就是这些地址所覆盖的范围。</p><p>在 BW100 的 DTK 环境中，从仓库根目录运行。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> experiments</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hipcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -std=c++17</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --offload-arch=gfx936</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 07_memory_latency_ladder.hip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 07_memory_latency_ladder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./07_memory_latency_ladder</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scalar</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./07_memory_latency_ladder</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scalar</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./07_memory_latency_ladder</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lane</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./07_memory_latency_ladder</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 48</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 64</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lane</span></span></code></pre></div><p>第一个参数是工作集大小（KiB），<code>42</code> 固定地址随机顺序的种子，<code>64</code> 是节点间距（字节）。<code>scalar</code> 和 <code>lane</code> 分别让编译器生成标量和向量加载。每个配置输出五轮，比较最后一列 <code>clock64_ticks_per_hop</code> 的中位数。</p><table tabindex="0"><thead><tr><th>路径</th><th style="text-align:right;">小工作集</th><th style="text-align:right;">较大工作集</th><th style="text-align:right;">BW100 复测中位数</th></tr></thead><tbody><tr><td>标量加载</td><td style="text-align:right;">16 KiB</td><td style="text-align:right;">24 KiB</td><td style="text-align:right;">约 58 → 220 tick/跳</td></tr><tr><td>向量加载</td><td style="text-align:right;">32 KiB</td><td style="text-align:right;">48 KiB</td><td style="text-align:right;">约 153 → 285 tick/跳</td></tr></tbody></table><p>没有卡时也可以读上表。先比较<strong>同一行</strong>的两个数，再把变慢前的工作集大小和驱动报告对照。稳定的延迟上升提示原来能更快取得的数据现在更难复用。每跳也包含循环和地址计算开销，读数会随设备配置变化。这个实验问的是等一次读取要多久。若要看许多线程一起工作时每秒能搬多少字节，可以做 E01 的带宽实验。<a href="./../labs/lab08-memory-latency-ladder.html">E06 完整扫点和源码</a> · <a href="./../labs/lab01-memory-coalescing.html">E01 带宽实验</a></p><details class="details custom-block"><summary>进阶阅读 · 合并访存、向量化和 LDS bank</summary><ul><li><strong>合并访存</strong>看同一个 wave 的相邻 lane 是否访问相邻地址。Lane 0–3 分别读 <code>a[0..3]</code>，通常比各自读间隔很远的位置更容易用少量内存事务完成。</li><li><strong>向量化访存</strong>看单个 lane 的一条指令能搬多少字节。满足对齐等条件且编译为宽指令时，<code>float4</code> 可以一次搬 16 字节。<a href="./../labs/lab01-memory-coalescing.html">E01 两组对照</a></li><li><strong>LDS bank 冲突</strong>看访问是否集中在同一个 bank 的不同地址。用 E02 的简化模型，每个对齐的 4 字节元素按 <code>元素索引 % 32</code> 分配 bank。索引 0、32、64 落在同一个 bank，把行跨度改为 33 后，索引 0、33、66 则落在不同 bank。访问同一个地址时，硬件可能广播。具体服务方式还取决于访问指令。<a href="./../labs/lab02-lds-bank-conflict.html">E02 LDS 实测</a></li></ul></details><h2 id="_6-思考题" tabindex="-1">6. 思考题 <a class="header-anchor" href="#_6-思考题" aria-label="Permalink to &quot;6. 思考题&quot;">​</a></h2><p>Wave A 写 LDS，Wave B 读这批数据。如果只让 Wave A 等待自己的写操作完成，Wave B 什么时候才可以安全读？</p><details class="details custom-block"><summary>查看答案</summary><p>Wave B 可能比 Wave A 更早到达读取位置。让同一 Block 的所有线程在写入后执行 <code>__syncthreads()</code>，再开始读取，就能协调读写双方。</p></details><p><a href="./../04-scheduling/occupancy-and-roofline.html">继续 1.4 · CU 如何减少等待造成的空闲</a></p>`,29))]))}});export{p as __pageData,k as default};
